cat > /app/output/styles.css << 'EOF'
:root {
  --bg: #f5f5f7;
  --surface: #ffffff;
  --text: #1d1d1f;
  --muted: #6e6e73;
  --link: #0066cc;
  --border: #d2d2d7;
  --radius: 18px;
  --shadow: 0 4px 20px rgba(0,0,0,0.06);
}
* { box-sizing: border-box; }
html { scroll-behavior: smooth; }
body {
  margin: 0;
  font-family: -apple-system, BlinkMacSystemFont, "SF Pro Text", "SF Pro Display", "Helvetica Neue", Arial, sans-serif;
  color: var(--text);
  background: #fff;
}
a { color: var(--link); text-decoration: none; }
a:hover { text-decoration: underline; }
.container { max-width: 1280px; margin: 0 auto; padding: 0 24px; }
.top-nav {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(255,255,255,0.9);
  backdrop-filter: saturate(180%) blur(14px);
  border-bottom: 1px solid #ececef;
}
.top-nav .container { display: flex; gap: 24px; align-items: center; padding: 14px 24px; }
.brand { font-weight: 700; letter-spacing: 0.1px; color: var(--text); }
.nav-links { display: flex; gap: 20px; flex-wrap: wrap; }
.nav-links a { color: #2a2a2d; font-size: 14px; }
.hero { background: var(--bg); padding: 54px 0 42px; }
.hero h1 { margin: 0; font-size: clamp(42px, 7vw, 56px); line-height: 1.05; }
.hero p { margin: 12px 0 0; color: var(--muted); font-size: 26px; font-weight: 500; }
.section { padding: 42px 0; }
.section h2 { font-size: clamp(28px, 4vw, 40px); margin: 0 0 22px; }
.carousel-wrap { position: relative; }
.carousel {
  display: flex;
  gap: 18px;
  overflow-x: auto;
  padding: 4px 6px 10px;
  scroll-snap-type: x mandatory;
  scrollbar-width: none;
}
.carousel::-webkit-scrollbar { display: none; }
.card {
  flex: 0 0 320px;
  min-height: 230px;
  background: var(--surface);
  border-radius: var(--radius);
  border: 1px solid #ededf0;
  box-shadow: var(--shadow);
  padding: 22px;
  scroll-snap-align: start;
}
.card h3 { margin: 0 0 8px; font-size: 24px; }
.card p { margin: 0 0 10px; color: var(--muted); line-height: 1.4; }
.price { font-weight: 600; margin-top: 8px; }
.img-box {
  height: 132px;
  border-radius: 12px;
  background: linear-gradient(145deg, #f8f8fb, #ececf3);
  margin-bottom: 16px;
}
.gradient-warm { background: linear-gradient(145deg, #fff8f0, #ffe5d1); }
.gradient-cool { background: linear-gradient(145deg, #eef6ff, #dfe9ff); }
.gradient-neutral { background: linear-gradient(145deg, #f8f8fb, #e8e8ee); }
.carousel-btn {
  position: absolute;
  top: 45%;
  transform: translateY(-50%);
  width: 40px;
  height: 40px;
  border-radius: 999px;
  border: 1px solid var(--border);
  background: #fff;
  color: #2d2d30;
  cursor: pointer;
}
.carousel-btn.prev { left: -8px; }
.carousel-btn.next { right: -8px; }
.carousel-btn:hover { background: #f8f8fa; }
.product-bar {
  display: flex;
  overflow-x: auto;
  gap: 20px;
  padding: 14px 2px;
  scrollbar-width: none;
}
.product-bar::-webkit-scrollbar { display: none; }
.product-pill {
  min-width: 120px;
  background: #fff;
  border: 1px solid #ececef;
  border-radius: 14px;
  padding: 14px;
  text-align: center;
}
.tile-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0,1fr));
  gap: 18px;
}
.tile {
  background: #fafafc;
  border-radius: 20px;
  padding: 28px;
  min-height: 370px;
  display: flex;
  flex-direction: column;
}
.tile .img-box { height: 180px; }
.tile h3 { font-size: 34px; margin: 0 0 8px; }
.tile p { color: var(--muted); margin: 0 0 18px; font-size: 18px; }
.cta-row { display: flex; gap: 18px; font-size: 17px; }
.tabs { display: flex; gap: 10px; flex-wrap: wrap; margin-bottom: 14px; }
.tab {
  border: 1px solid #d8d8de;
  border-radius: 999px;
  background: #fff;
  padding: 10px 16px;
  cursor: pointer;
}
.tab.active { background: #1d1d1f; color: #fff; border-color: #1d1d1f; }
.tab-panels .panel { display: none; }
.tab-panels .panel.active { display: block; }
.sticky-subnav {
  position: sticky;
  top: 49px;
  background: rgba(255,255,255,0.93);
  backdrop-filter: blur(10px);
  z-index: 80;
  border-bottom: 1px solid #ececf1;
}
.subnav-links {
  display: flex;
  gap: 16px;
  overflow-x: auto;
  padding: 12px 0;
  scrollbar-width: none;
}
.subnav-links::-webkit-scrollbar { display: none; }
.subnav-links a { white-space: nowrap; color: #444; font-size: 14px; }
.footer {
  margin-top: 56px;
  background: var(--bg);
  border-top: 1px solid #e3e3e8;
}
.footer-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0,1fr));
  gap: 20px;
  padding: 28px 0 34px;
}
.footer h4 { margin: 0 0 10px; font-size: 14px; }
.footer ul { margin: 0; padding: 0; list-style: none; }
.footer li { margin: 8px 0; }
.footer a { color: #56565b; font-size: 13px; }
.footer-accordion-btn { display: none; width: 100%; text-align: left; border: none; background: none; padding: 12px 0; font-size: 14px; }
@media (max-width: 900px) {
  .tile-grid { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr 1fr; }
}
@media (max-width: 700px) {
  .container { padding: 0 16px; }
  .card { flex-basis: 86vw; }
  .hero p { font-size: 22px; }
  .footer-grid { grid-template-columns: 1fr; }
  .footer-column ul { display: none; }
  .footer-accordion-btn { display: block; }
  .footer-column.open ul { display: block; }
}
EOF

cat > /app/output/main.js << 'EOF'
function setupCarousels() {
  document.querySelectorAll('[data-carousel]').forEach((wrap) => {
    const track = wrap.querySelector('.carousel');
    const prev = wrap.querySelector('.carousel-btn.prev');
    const next = wrap.querySelector('.carousel-btn.next');
    if (!track || !prev || !next) return;
    const scrollAmt = () => Math.max(track.clientWidth * 0.82, 260);
    prev.addEventListener('click', () => track.scrollBy({ left: -scrollAmt(), behavior: 'smooth' }));
    next.addEventListener('click', () => track.scrollBy({ left: scrollAmt(), behavior: 'smooth' }));
  });
}

function setupTabs() {
  const tabsRoot = document.querySelector('[data-tabs]');
  if (!tabsRoot) return;
  const tabs = tabsRoot.querySelectorAll('.tab');
  const panels = tabsRoot.querySelectorAll('.panel');
  tabs.forEach((tab) => {
    tab.addEventListener('click', () => {
      const target = tab.dataset.target;
      tabs.forEach((t) => t.classList.remove('active'));
      panels.forEach((p) => p.classList.remove('active'));
      tab.classList.add('active');
      tabsRoot.querySelector(`#${target}`)?.classList.add('active');
    });
  });
}

function setupFooterAccordion() {
  document.querySelectorAll('.footer-accordion-btn').forEach((btn) => {
    btn.addEventListener('click', () => {
      btn.closest('.footer-column')?.classList.toggle('open');
    });
  });
}

document.addEventListener('DOMContentLoaded', () => {
  setupCarousels();
  setupTabs();
  setupFooterAccordion();
});
EOF

